  "headline": "FDA's records show the cisplatin shortage has been listed for 44 months and the Thymoorgan Pharmazie GmbH plant in Germany received VAI classifications in 2022 and 2023",
  "headline_cites": ["D5", "E10", "E11"],
  "sentences": [
    {
      "text": "As of 2026-10-21 the cisplatin shortage has been on FDA's shortage list for 44 months since the original posting on 2023-02-10.",
      "cites": ["D5"]
    },
    {
      "text": "FDA inspection 1207607 at the Thymoorgan Pharmazie GmbH plant in Germany ended on 2022-10-06 and was classified VAI, which was 127 days before FDA posted the shortage on 2023-02-10.",
      "cites": ["D3", "E10"]
    },
    {
      "text": "FDA inspection 1203954 at the same Thymoorgan Pharmazie GmbH plant ended on 2023-04-25 and was classified VAI, with the classification letter dated 2023-07-10, which was 74 days after the shortage posting.",
      "cites": ["D4", "E11"]
    },
    {
      "text": "The Thymoorgan Pharmazie GmbH plant is named on a cisplatin label (NDC 00143950401) from Hikma Pharmaceuticals USA Inc. with operations including manufacture, pack, and analysis.",
      "cites": ["E12"]
    },
    {
      "text": "Corvale East holds 166 units at 9.3 units per day for 18 days on hand, while Corvale General holds 270 units at 8.7 units per day for 31 days on hand.",
      "cites": ["D1", "D2"]
    }
  ]
}
